import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address to = address(0x1234);
        address from = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

        // Record balance of recipient before
        uint256 balanceBefore = to.balance;

        // Call transfer with one recipient and value 1 (so mul gives 1e18 wei)
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory v = new uint[](1);
        v[0] = 1;

        vm.prank(from);
        c.transfer(tos, v);

        // After reference call, to.balance increases by 1e18; after mutant, no change
        uint256 balanceAfter = to.balance;
        // The reference makes the transfer, so balance increases; the mutant does not
        // We assert that the balance changed (which only the reference does)
        assertTrue(balanceAfter > balanceBefore);
    }
}

