pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a helper contract that records the number of incoming calls
        // and set it as caddress
        CallRecorder rec = new CallRecorder();
        // Use vm.store to replace the caddress storage slot (slot 1) with rec's address
        vm.store(address(c), bytes32(uint256(1)), bytes32(uint256(uint160(address(rec)))));

        // Authorized caller
        address sender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(sender);
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint[] memory vals = new uint[](1);
        vals[0] = 1;
        c.transfer(tos, vals);

        // After transfer, the reference should have made one call to rec, so rec.counter() == 1
        // The buggy version makes zero calls, so counter() == 0
        assertTrue(rec.counter() == 1, "Reference should increment counter");
        // Actually we need it to PASS on reference, FAIL on bug: so we assert the reference behavior
        // For buggy version, this assertion fails because rec.counter() == 0
        assertTrue(rec.counter() == 1);
    }
}

contract CallRecorder {
    uint public counter;
    fallback() external payable { counter++; }
}

