pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: from address and token contract address are fixed in C
        address from = c.from();
        address token = c.caddress();
        address caller = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

        // Prepare inputs: one recipient, amount 1 wei (in eth units)
        address[] memory tos = new address[](1);
        tos[0] = address(0x123);
        uint[] memory vals = new uint[](1);
        vals[0] = 1;

        // Record balances before
        uint balFromBefore = address(from).balance;
        uint balTokenBefore = address(token).balance;

        // Call transfer
        vm.prank(caller);
        c.transfer(tos, vals);

        // The reference: token.transferFrom(from, recipient, 1e18) should transfer from token to from? No, transferFrom moves tokens from 'from' to recipient.
        // Actually the reference calls transferFrom(c.from, _tos[i], value) meaning it moves tokens from c.from() to _tos[0].
        // So after call, c.from()'s token balance at token contract should decrease by 1e18,
        // and _tos[0]'s token balance should increase by 1e18.
        // The bug calls transferFrom(_tos[i], c.from, value) moving tokens from recipient to c.from().
        // So the two diverge in the balance of c.from() at token contract.
        // We can observe this via the token contract's public getter, but C does not expose balances directly.
        // However, the difference is that c.from() itself remains unchanged as an address state.
        // The only observable state variable is c.from() — it is a fixed address set in constructor, never modified.
        // Actually, the mutation changes the argument order in the call, not state variable assignments.
        // The only way to observe divergence is through the token contract's state.
        // Since we cannot read token contract's state directly, we use try/catch to detect revert?
        // The function does not revert in either case for valid inputs.

        // Alternative: check that c.from() still equals the original (always true) — both reference and bug keep it same.
        // Actually the test must find an observable difference. The only public variable we can read is 'from' and 'caddress'
        // both unchanged. address(c).balance is 0. The function returns true always.
        // So the only way is to observe token contract's balance via low-level call.
        // We can query the token contract (c.caddress()) using its expected interface.
        // The token contract is not defined, but we can still call it via .call with balanceOf selector.
        // Let's query balanceOf(from) before and after.
        bytes4 balanceOfSig = bytes4(keccak256("balanceOf(address)"));
        (bool success1, bytes memory data1) = address(token).call(abi.encodeWithSelector(balanceOfSig, from));
        uint balFromBefore2 = abi.decode(data1, (uint256));

        // Now call transfer again (same caller)
        vm.prank(caller);
        c.transfer(tos, vals);

        (bool success2, bytes memory data2) = address(token).call(abi.encodeWithSelector(balanceOfSig, from));
        uint balFromAfter = abi.decode(data2, (uint256));

        // In reference: balFromBefore2 - balFromAfter == 1e18 (from lost tokens)
        // In bug: balFromAfter - balFromBefore2 == 1e18 (from gained tokens)
        // So assert that balFromAfter < balFromBefore2 (reference)
        assertTrue(balFromAfter < balFromBefore2);
    }
}

