pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // In the reference, transferFrom(from, recipient, value) is called.
        // In the bug, transferFrom(recipient, from, value) is called — recipient has no approval/balance → reverts.
        address from = c.from();
        address recipient = address(0x1234);
        address[] memory tos = new address[](1);
        tos[0] = recipient;
        uint[] memory amounts = new uint[](1);
        amounts[0] = 1;
        vm.prank(from);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transfer(address[],uint256[])", tos, amounts));
        assertTrue(ok, "transfer should succeed on reference; bug fails");
    }
}
